package com.vidhura.ai.recommendation.model;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.index.CompoundIndex;
import org.springframework.data.mongodb.core.index.CompoundIndexes;
import org.springframework.data.mongodb.core.index.Indexed;
import org.springframework.data.mongodb.core.mapping.Document;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

/**
 * Persisted validation results generated by the automated evidence validation engine (Phase 3.9).
 * Decoupled from human reviewer decisions (VERIFIED_STATUTORY vs REJECTED).
 *
 * Strict Provenance Rule:
 * Automated validation never sets verifiedBy, verifiedAt, or VERIFIED_STATUTORY.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
@Document(collection = "external_evidence_validation_results")
@CompoundIndexes({
        @CompoundIndex(name = "evidence_rec_rev_idx", def = "{'evidenceRecordId': 1, 'recordRevision': 1}"),
        @CompoundIndex(name = "priority_score_idx", def = "{'reviewPriorityScore': -1, 'validatedAt': -1}")
})
public class ExternalEvidenceValidationResult {

    @Id
    private String id;

    @Indexed
    private String evidenceRecordId;

    private int recordRevision;

    @Indexed
    private String insurerCode;

    @Indexed
    private String metricKey;

    private String metricCategory;

    @Indexed
    private Instant validatedAt;

    /**
     * Overall validation status:
     * VALIDATION_PASSED, VALIDATION_PASSED_WITH_WARNINGS, VALIDATION_FAILED, VALIDATION_NOT_RUN
     */
    @Indexed
    private String overallOutcome;

    /**
     * Deterministic review-priority score (higher = higher urgency):
     * BLOCKER = +100, ERROR = +50, WARNING = +10, INFO = +1, Staged Revision = +15, Material = +5
     */
    @Indexed
    private int reviewPriorityScore;

    /**
     * CRITICAL (>= 100), HIGH (50-99), MEDIUM (10-49), LOW (< 10)
     */
    @Indexed
    private String priorityTier;

    @Builder.Default
    private List<ValidationFinding> findings = new ArrayList<>();

    @Builder.Default
    private String validatorVersion = "1.0.0-phase3.9";

    private String summary;

    @Data
    @Builder
    @NoArgsConstructor
    @AllArgsConstructor
    public static class ValidationFinding {
        /**
         * Category: SOURCE_INTEGRITY, CITATION, NUMERICAL_CALCULATION, SEMANTICS_GOVERNANCE, FRESHNESS_REVISION
         */
        private String checkCategory;

        /**
         * Machine-readable finding code (e.g. DOC_HASH_MISMATCH, CALC_REPRODUCTION_MISMATCH)
         */
        private String findingCode;

        /**
         * Severity: BLOCKER, ERROR, WARNING, INFO
         */
        private String severity;

        /**
         * Human-readable explanation of why this check failed or raised a warning
         */
        private String message;

        private String expectedValue;

        private String actualValue;

        private String affectedDocument;

        private String citation;
    }
}
